//! Transactional cache-group certificate layer.
//!
//! This module implements the committed-state certificates and the exact
//! proposal violation counts described in PROTOCOL.md.  The committed state is
//! kept in a set of flat arrays together with incrementally maintained
//! derived quantities (per-group footprints, per-node reservations, group
//! loads, distinct (domain, class) pair counts and the four violation
//! counters).  A transaction is applied directly on top of the committed
//! state while a journal of the previous field values is recorded; a rejected
//! proposal is rolled back by replaying that journal in reverse order, which
//! restores every committed value exactly.

use crate::solver::SolverProblem;
use std::collections::HashMap;

const NONE: usize = usize::MAX;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize),
    Weight(usize, u64),
    Class(usize, u64),
    Bind(usize, usize),
    Pin(usize, bool),
    Quota(usize, u64),
    Budget(usize, u64),
    Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query {
    pub groups: Vec<usize>,
    pub nodes: Vec<usize>,
    pub tasks: Vec<usize>,
}

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

#[derive(Clone, Copy)]
struct Snap {
    group: usize,
    tpl: usize,
    weight: u64,
    class: u64,
    pin: bool,
}

pub struct Ledger {
    // sizes
    n: usize,
    words: usize,
    tcount: usize,
    gcount: usize,

    // static template data
    tpl_domain: Vec<u64>,
    tpl_words: Vec<u64>,

    // task state
    t_group: Vec<usize>,
    t_tpl: Vec<usize>,
    t_weight: Vec<u64>,
    t_class: Vec<u64>,
    t_pin: Vec<bool>,
    t_prev: Vec<usize>,
    t_next: Vec<usize>,

    // group / node state
    quota: Vec<u64>,
    budget: Vec<u64>,
    cap: Vec<u64>,

    // group derived state
    g_members: Vec<u32>,
    g_load: Vec<u64>,
    g_fp_size: Vec<u32>,
    g_ref: Vec<u32>,
    g_head: Vec<usize>,
    g_pin: Vec<u32>,
    g_distinct: Vec<u32>,
    pairs: HashMap<(usize, u64, u64), u32>,

    // node derived state
    usage: Vec<u64>,

    // global counters
    total_slots: u64,
    total_weight: u64,
    pinned_total: u32,
    active: usize,
    over_cap: usize,
    mixed: usize,
    work_bad: usize,
    revision: u64,

    // transaction scratch space
    tx_id: u32,
    tx_stamp: Vec<u32>,
    tx_snap: Vec<Snap>,
    tx_f: Vec<bool>,
    tx_gstamp: Vec<u32>,
    tx_gq0: Vec<u64>,
    tx_gclean: Vec<u32>,
    tx_gmark: Vec<usize>,
    tx_fcount: usize,
    journal: Vec<(u8, usize, u64)>,
    journaling: bool,
    tracking: bool,
}

fn encode(edit: &Edit) -> (u8, usize, u64) {
    match *edit {
        Edit::Move(id, value) => (0, id, value as u64),
        Edit::Weight(id, value) => (1, id, value),
        Edit::Class(id, value) => (2, id, value),
        Edit::Bind(id, value) => (3, id, value as u64),
        Edit::Pin(id, value) => (4, id, value as u64),
        Edit::Quota(id, value) => (5, id, value),
        Edit::Budget(id, value) => (6, id, value),
        Edit::Cap(id, value) => (7, id, value),
    }
}

fn task_of(edit: &Edit) -> Option<usize> {
    match *edit {
        Edit::Move(id, _)
        | Edit::Weight(id, _)
        | Edit::Class(id, _)
        | Edit::Bind(id, _)
        | Edit::Pin(id, _) => Some(id),
        _ => None,
    }
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let n = problem.num_nodes;
        if capacities.len() != n {
            return Err("capacity count".into());
        }
        if quotas.len() != budgets.len() {
            return Err("group count".into());
        }
        let gcount = quotas.len();
        if gcount == 0 {
            return Err("no groups".into());
        }
        let words = if n == 0 { 0 } else { (n + 63) / 64 };
        let tcount = problem.demands.len();

        // template domains and footprints (as bit sets)
        let mut src_group = vec![NONE; n];
        for (gid, group) in problem.source_merge_groups.iter().enumerate() {
            for &node in group {
                if node < n && src_group[node] == NONE {
                    src_group[node] = gid;
                }
            }
        }
        let classes = problem.demand_merge_classes.as_ref();
        let mut tpl_domain = Vec::with_capacity(tcount);
        let mut tpl_words = vec![0u64; tcount.checked_mul(words).ok_or("size")?];
        for (t, demand) in problem.demands.iter().enumerate() {
            let dom = match classes {
                Some(c) => {
                    if t >= c.len() {
                        return Err("merge class".into());
                    }
                    c[t] as u64
                }
                None => {
                    if demand.src >= n || src_group[demand.src] == NONE {
                        return Err("domain".into());
                    }
                    src_group[demand.src] as u64
                }
            };
            tpl_domain.push(dom);
            if demand.footprint.is_empty() {
                return Err("empty footprint".into());
            }
            for &node in &demand.footprint {
                if node >= n {
                    return Err("footprint node".into());
                }
                tpl_words[t * words + node / 64] |= 1u64 << (node % 64);
            }
        }

        let dcount = tasks.len();
        let mut led = Ledger {
            n,
            words,
            tcount,
            gcount,
            tpl_domain,
            tpl_words,
            t_group: vec![0; dcount],
            t_tpl: vec![0; dcount],
            t_weight: vec![0; dcount],
            t_class: vec![0; dcount],
            t_pin: vec![false; dcount],
            t_prev: vec![NONE; dcount],
            t_next: vec![NONE; dcount],
            quota,
            budget,
            cap: capacities,
            g_members: vec![0; gcount],
            g_load: vec![0; gcount],
            g_fp_size: vec![0; gcount],
            g_ref: vec![0; gcount.checked_mul(n).ok_or("size")?],
            g_head: vec![NONE; gcount],
            g_pin: vec![0; gcount],
            g_distinct: vec![0; gcount],
            pairs: HashMap::with_capacity(dcount.saturating_mul(2)),
            usage: vec![0; n],
            total_slots: 0,
            total_weight: 0,
            pinned_total: 0,
            active: 0,
            over_cap: 0,
            mixed: 0,
            work_bad: 0,
            revision: 0,
            tx_id: 0,
            tx_stamp: vec![0; dcount],
            tx_snap: vec![
                Snap {
                    group: 0,
                    tpl: 0,
                    weight: 0,
                    class: 0,
                    pin: false,
                };
                dcount
            ],
            tx_f: vec![false; dcount],
            tx_gstamp: vec![0; gcount],
            tx_gq0: vec![0; gcount],
            tx_gclean: vec![0; gcount],
            tx_gmark: Vec::new(),
            tx_fcount: 0,
            journal: Vec::new(),
            journaling: false,
            tracking: false,
        };

        for (t, task) in tasks.iter().enumerate() {
            if task.template >= tcount || task.group >= gcount {
                return Err("task id".into());
            }
            led.t_tpl[t] = task.template;
            led.t_group[t] = task.group;
            led.t_weight[t] = task.weight;
            led.t_class[t] = task.class;
            led.t_pin[t] = task.pinned;
            if task.pinned {
                led.pinned_total += 1;
                led.g_pin[task.group] += 1;
            }
        }
        for t in 0..dcount {
            let g = led.t_group[t];
            led.add_task(t, g);
        }
        led.total_weight = tasks.iter().map(|t| t.weight).sum();

        if led.over_cap != 0 || led.mixed != 0 || led.work_bad != 0 {
            return Err("illegal initial configuration".into());
        }
        Ok(led)
    }

    // ---- primitive helpers ----------------------------------------------

    #[inline]
    fn work_pred(&self, g: usize) -> bool {
        self.g_members[g] > 0
            && (self.quota[g] == 0 || self.g_load[g] > self.quota[g].saturating_mul(self.budget[g]))
    }

    #[inline]
    fn work_check(&mut self, g: usize, was: bool) {
        let now = self.work_pred(g);
        if now != was {
            if now {
                self.work_bad += 1;
            } else {
                self.work_bad -= 1;
            }
        }
    }

    #[inline]
    fn usage_add(&mut self, v: usize, q: u64) {
        let was_over = self.usage[v] > self.cap[v];
        self.usage[v] += q;
        self.total_slots += q;
        let over = self.usage[v] > self.cap[v];
        if over != was_over {
            if over {
                self.over_cap += 1;
            } else {
                self.over_cap -= 1;
            }
        }
    }

    #[inline]
    fn usage_sub(&mut self, v: usize, q: u64) {
        let was_over = self.usage[v] > self.cap[v];
        self.usage[v] = self.usage[v].saturating_sub(q);
        self.total_slots = self.total_slots.saturating_sub(q);
        let over = self.usage[v] > self.cap[v];
        if over != was_over {
            if over {
                self.over_cap += 1;
            } else {
                self.over_cap -= 1;
            }
        }
    }

    #[inline]
    fn pair_inc(&mut self, g: usize, dom: u64, cls: u64) {
        let cnt = self.pairs.entry((g, dom, cls)).or_insert(0);
        *cnt += 1;
        if *cnt == 1 {
            self.g_distinct[g] += 1;
            if self.g_distinct[g] == 2 {
                self.mixed += 1;
            }
        }
    }

    #[inline]
    fn pair_dec(&mut self, g: usize, dom: u64, cls: u64) {
        let mut dead = false;
        let mut two = false;
        if let Some(cnt) = self.pairs.get_mut(&(g, dom, cls)) {
            if *cnt > 0 {
                *cnt -= 1;
                if *cnt == 0 {
                    dead = true;
                }
            }
        }
        if dead {
            let d = self.g_distinct[g];
            self.g_distinct[g] = d - 1;
            if d == 2 {
                two = true;
            }
        }
        if two {
            self.mixed -= 1;
        }
    }

    #[inline]
    fn link(&mut self, t: usize, g: usize) {
        let h = self.g_head[g];
        self.t_next[t] = h;
        self.t_prev[t] = NONE;
        if h != NONE {
            self.t_prev[h] = t;
        }
        self.g_head[g] = t;
    }

    #[inline]
    fn unlink(&mut self, t: usize) {
        let p = self.t_prev[t];
        let nx = self.t_next[t];
        if p != NONE {
            self.t_next[p] = nx;
        } else {
            let g = self.t_group[t];
            self.g_head[g] = nx;
        }
        if nx != NONE {
            self.t_prev[nx] = p;
        }
        self.t_prev[t] = NONE;
        self.t_next[t] = NONE;
    }

    /// Remove the reservations of `t`'s current template footprint from group `g`.
    /// The group must currently be non-empty.
    fn footprint_remove(&mut self, t: usize, g: usize, tpl: usize) {
        let base = g * self.n;
        let tbase = tpl * self.words;
        let nwords = self.words;
        let q = self.quota[g];
        for wi in 0..nwords {
            let mut word = self.tpl_words[tbase + wi];
            while word != 0 {
                let v = wi * 64 + word.trailing_zeros() as usize;
                word &= word - 1;
                let idx = base + v;
                let rc = self.g_ref[idx];
                if rc == 1 {
                    self.usage_sub(v, q);
                    self.g_fp_size[g] -= 1;
                }
                self.g_ref[idx] = rc - 1;
            }
        }
    }

    /// Add the reservations of `tpl`'s footprint to group `g`.
    /// The group must already be counted as non-empty.
    fn footprint_add(&mut self, g: usize, tpl: usize) {
        let base = g * self.n;
        let tbase = tpl * self.words;
        let nwords = self.words;
        let q = self.quota[g];
        for wi in 0..nwords {
            let mut word = self.tpl_words[tbase + wi];
            while word != 0 {
                let v = wi * 64 + word.trailing_zeros() as usize;
                word &= word - 1;
                let idx = base + v;
                let rc = self.g_ref[idx];
                if rc == 0 {
                    self.usage_add(v, q);
                    self.g_fp_size[g] += 1;
                }
                self.g_ref[idx] = rc + 1;
            }
        }
    }

    fn remove_task(&mut self, t: usize, g: usize) {
        let was = self.work_pred(g);
        let w = self.t_weight[t];
        let tpl = self.t_tpl[t];
        let dom = self.tpl_domain[tpl];
        let cls = self.t_class[t];
        self.pair_dec(g, dom, cls);
        self.unlink(t);
        self.g_load[g] -= w;
        self.footprint_remove(t, g, tpl);
        let m = self.g_members[g] - 1;
        self.g_members[g] = m;
        if m == 0 {
            self.active -= 1;
        }
        self.work_check(g, was);
    }

    fn add_task(&mut self, t: usize, g: usize) {
        let was = self.work_pred(g);
        let w = self.t_weight[t];
        let m = self.g_members[g] + 1;
        self.g_members[g] = m;
        if m == 1 {
            self.active += 1;
        }
        self.g_load[g] += w;
        self.footprint_add(g, self.t_tpl[t]);
        self.link(t, g);
        let dom = self.tpl_domain[self.t_tpl[t]];
        let cls = self.t_class[t];
        self.pair_inc(g, dom, cls);
        self.work_check(g, was);
    }

    fn set_quota(&mut self, g: usize, old: u64, new: u64) {
        let base = g * self.n;
        let n = self.n;
        let delta = new as i64 - old as i64;
        for v in 0..n {
            if self.g_ref[base + v] > 0 {
                let was_over = self.usage[v] > self.cap[v];
                let u = self.usage[v] as i64 + delta;
                self.usage[v] = if u < 0 { 0 } else { u as u64 };
                let s = self.total_slots as i64 + delta;
                self.total_slots = if s < 0 { 0 } else { s as u64 };
                let over = self.usage[v] > self.cap[v];
                if over != was_over {
                    if over {
                        self.over_cap += 1;
                    } else {
                        self.over_cap -= 1;
                    }
                }
            }
        }
    }

    /// Apply one field assignment.  When journaling is enabled the previous
    /// value is recorded so that the edit can be rolled back.
    fn apply(&mut self, code: u8, id: usize, value: u64) {
        match code {
            0 => {
                let old = self.t_group[id];
                let new = value as usize;
                if old == new {
                    return;
                }
                if self.journaling {
                    self.journal.push((0, id, old as u64));
                }
                self.remove_task(id, old);
                self.t_group[id] = new;
                self.add_task(id, new);
            }
            1 => {
                let old = self.t_weight[id];
                if old == value {
                    return;
                }
                if self.journaling {
                    self.journal.push((1, id, old));
                }
                let g = self.t_group[id];
                let was = self.work_pred(g);
                self.g_load[g] = self.g_load[g] - old + value;
                self.total_weight = self.total_weight - old + value;
                self.t_weight[id] = value;
                self.work_check(g, was);
            }
            2 => {
                let old = self.t_class[id];
                if old == value {
                    return;
                }
                if self.journaling {
                    self.journal.push((2, id, old));
                }
                let g = self.t_group[id];
                let dom = self.tpl_domain[self.t_tpl[id]];
                self.pair_dec(g, dom, old);
                self.t_class[id] = value;
                self.pair_inc(g, dom, value);
            }
            3 => {
                let old = self.t_tpl[id];
                let new = value as usize;
                if old == new {
                    return;
                }
                if self.journaling {
                    self.journal.push((3, id, old as u64));
                }
                let g = self.t_group[id];
                let old_dom = self.tpl_domain[old];
                let new_dom = self.tpl_domain[new];
                let cls = self.t_class[id];
                self.footprint_remove(id, g, old);
                self.t_tpl[id] = new;
                self.footprint_add(g, new);
                if old_dom != new_dom || true {
                    self.pair_dec(g, old_dom, cls);
                    self.pair_inc(g, new_dom, cls);
                }
            }
            4 => {
                let old = self.t_pin[id];
                let new = value != 0;
                if old == new {
                    return;
                }
                if self.journaling {
                    self.journal.push((4, id, old as u64));
                }
                self.t_pin[id] = new;
                let g = self.t_group[id];
                if new {
                    self.pinned_total += 1;
                    self.g_pin[g] += 1;
                } else {
                    self.pinned_total -= 1;
                    self.g_pin[g] -= 1;
                }
            }
            5 => {
                let g = id;
                let old = self.quota[g];
                if old == value {
                    return;
                }
                if self.journaling {
                    self.journal.push((5, g, old));
                }
                let was = self.work_pred(g);
                self.set_quota(g, old, value);
                self.quota[g] = value;
                self.work_check(g, was);
            }
            6 => {
                let g = id;
                let old = self.budget[g];
                if old == value {
                    return;
                }
                if self.journaling {
                    self.journal.push((6, g, old));
                }
                let was = self.work_pred(g);
                self.budget[g] = value;
                self.work_check(g, was);
            }
            7 => {
                let v = id;
                let old = self.cap[v];
                if old == value {
                    return;
                }
                if self.journaling {
                    self.journal.push((7, v, old));
                }
                let was_over = self.usage[v] > old;
                self.cap[v] = value;
                let over = self.usage[v] > value;
                if over != was_over {
                    if over {
                        self.over_cap += 1;
                    } else {
                        self.over_cap -= 1;
                    }
                }
            }
            _ => return,
        }
        if code <= 3 && self.tracking {
            self.track_pin(id);
        }
    }

    /// Recompute the pin-protection state of a task whose group, template,
    /// weight or class may just have changed.
    fn track_pin(&mut self, t: usize) {
        if self.tx_stamp[t] != self.tx_id {
            return;
        }
        let s = self.tx_snap[t];
        if !s.pin {
            return;
        }
        let f = self.t_group[t] != s.group
            || self.t_tpl[t] != s.tpl
            || self.t_weight[t] != s.weight
            || self.t_class[t] != s.class;
        if f != self.tx_f[t] {
            self.tx_f[t] = f;
            if f {
                self.tx_fcount += 1;
                if self.tx_gclean[s.group] > 0 {
                    self.tx_gclean[s.group] -= 1;
                }
            } else {
                self.tx_fcount -= 1;
                self.tx_gclean[s.group] += 1;
            }
        }
    }

    fn mark_group(&mut self, g: usize, tx: u32) {
        if self.tx_gstamp[g] == tx {
            return;
        }
        self.tx_gstamp[g] = tx;
        self.tx_gq0[g] = self.quota[g];
        self.tx_gclean[g] = self.g_pin[g];
        self.tx_gmark.push(g);
    }

    // ---- public API ------------------------------------------------------

    pub fn certificate(&self, query: &Query) -> Certificate {
        let totals = [
            self.active as u64,
            self.total_slots,
            self.total_weight,
            self.pinned_total as u64,
        ];
        let mut groups = Vec::with_capacity(query.groups.len());
        for &g in &query.groups {
            if g >= self.gcount {
                continue;
            }
            let (dom, cls) = if self.g_members[g] > 0 {
                let h = self.g_head[g];
                if h == NONE {
                    (-1i64, -1i64)
                } else {
                    (self.tpl_domain[self.t_tpl[h]] as i64, self.t_class[h] as i64)
                }
            } else {
                (-1i64, -1i64)
            };
            groups.push([
                g as i64,
                self.g_members[g] as i64,
                self.g_load[g] as i64,
                self.quota[g] as i64,
                self.budget[g] as i64,
                self.g_fp_size[g] as i64,
                dom,
                cls,
            ]);
        }
        let mut nodes = Vec::with_capacity(query.nodes.len());
        for &v in &query.nodes {
            if v >= self.n {
                continue;
            }
            nodes.push([v as u64, self.usage[v], self.cap[v]]);
        }
        let mut tasks = Vec::with_capacity(query.tasks.len());
        for &t in &query.tasks {
            if t >= self.t_pin.len() {
                continue;
            }
            tasks.push([
                t as u64,
                self.t_group[t] as u64,
                self.t_tpl[t] as u64,
                self.t_weight[t],
                self.t_class[t],
                if self.t_pin[t] { 1 } else { 0 },
            ]);
        }
        Certificate {
            totals,
            groups,
            nodes,
            tasks,
        }
    }

    pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
        if expected != self.revision {
            let certificate = self.certificate(query);
            return Outcome {
                accepted: false,
                revision: self.revision,
                violations: None,
                certificate,
            };
        }

        self.tx_id = self.tx_id.wrapping_add(1);
        let tx = self.tx_id;
        // First pass: snapshot every task touched by this transaction so the
        // pin protection is evaluated against the beginning-of-transaction
        // state.
        for edit in edits {
            if let Some(t) = task_of(edit) {
                if t < self.tx_stamp.len() && self.tx_stamp[t] != tx {
                    self.tx_stamp[t] = tx;
                    self.tx_snap[t] = Snap {
                        group: self.t_group[t],
                        tpl: self.t_tpl[t],
                        weight: self.t_weight[t],
                        class: self.t_class[t],
                        pin: self.t_pin[t],
                    };
                    self.tx_f[t] = false;
                }
            }
        }
        // Second pass: mark the groups whose beginning-of-transaction quota
        // and protected-task count are needed.
        self.tx_gmark.clear();
        for edit in edits {
            match *edit {
                Edit::Quota(g, _) => {
                    if g < self.gcount {
                        self.mark_group(g, tx);
                    }
                }
                Edit::Move(t, _)
                | Edit::Weight(t, _)
                | Edit::Class(t, _)
                | Edit::Bind(t, _) => {
                    if t < self.tx_stamp.len() && self.tx_stamp[t] == tx {
                        let g = self.tx_snap[t].group;
                        if self.tx_snap[t].pin && g < self.gcount {
                            self.mark_group(g, tx);
                        }
                    }
                }
                _ => {}
            }
        }

        self.tx_fcount = 0;
        self.journal.clear();
        self.journaling = true;
        self.tracking = true;
        for edit in edits {
            let (code, id, value) = encode(edit);
            self.apply(code, id, value);
        }
        self.tracking = false;
        self.journaling = false;

        let mut pins = self.tx_fcount;
        for index in 0..self.tx_gmark.len() {
            let g = self.tx_gmark[index];
            if self.quota[g] != self.tx_gq0[g] {
                pins += self.tx_gclean[g] as usize;
            }
        }

        let violations = [
            self.over_cap as u64,
            self.mixed as u64,
            self.work_bad as u64,
            pins as u64,
        ];
        let accepted = violations == [0, 0, 0, 0];
        if accepted {
            self.revision += 1;
            self.journal.clear();
        } else {
            // Roll the proposal back: replaying the recorded previous values
            // in reverse order restores every committed field exactly.
            let journal = std::mem::take(&mut self.journal);
            for index in (0..journal.len()).rev() {
                let (code, id, value) = journal[index];
                self.apply(code, id, value);
            }
            self.journal = journal;
            self.journal.clear();
        }

        let certificate = self.certificate(query);
        Outcome {
            accepted,
            revision: self.revision,
            violations: Some(violations),
            certificate,
        }
    }
}
